mapper.select:
SELECT id, tenant_id, message_title, message_content, receiver_id,
       read_status, msg_type_id, source_type, status,
       create_time, update_time, creator_id, updater_id, is_deleted,
       owner_dept_id, owner_id, version
FROM msg_message
WHERE tenant_id = #{query.tenantId}
  AND is_deleted = FALSE

    AND message_title LIKE CONCAT('%', #{query.messageTitle}, '%')


    AND read_status = #{query.readStatus}


    AND msg_type_id = #{query.msgTypeId}


    AND receiver_id = #{query.receiverId}

ORDER BY create_time DESC
